<?php
/* Naše TV – Programové studio: přístup jen s heslem (dočasné, než bude v portálu přihlášení s rolemi) */
session_set_cookie_params(['httponly'=>true,'secure'=>true,'samesite'=>'Strict']);
session_start();
header('X-Robots-Tag: noindex, nofollow');
header('X-Frame-Options: SAMEORIGIN');
const NTV_HASH='c794b4ae4136e310fcc953f8a5fc0ee3804536bc409dfe1079784c83585042c6';
if(isset($_GET['odhlasit'])){$_SESSION=[];session_destroy();header('Location: ./');exit;}
$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  usleep(400000);
  if(hash_equals(NTV_HASH,hash('sha256',(string)($_POST['heslo']??'')))){session_regenerate_id(true);$_SESSION['ntv_ok']=1;header('Location: ./');exit;}
  $err='Nesprávné heslo.';
}
if(empty($_SESSION['ntv_ok'])){ ?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Naše TV – přihlášení do studia</title>
