<body><form method="post"><h2 style="margin:0">Naše TV · Programové studio</h2><p style="color:#56627a">Administrace – jen pro redakci.</p><?php if($err) echo '<p class="e">'.$err.'</p>'; ?><input type="password" name="heslo" placeholder="Heslo" autofocus required><button>Přihlásit</button></form></body></html>
<?php exit; }
