grid-template-columns:140px 1fr 62px;gap:8px;align-items:center;font-size:13px;padding:2px 0}.sbar .st{background:var(--btn);border-radius:6px;height:12px;overflow:hidden}.sbar .st i{display:block;height:100%;background:linear-gradient(90deg,#3b6fd8,#22a6a6);border-radius:6px}.sbar .sv{text-align:right;font-variant-numeric:tabular-nums}.donut{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:6px}.hours{display:grid;grid-template-columns:repeat(24,1fr);gap:2px;height:120px;align-items:end}.hours div{display:flex;flex-direction:column;justify-content:flex-end;height:100%;font-size:10px;text-align:center;color:var(--mut)}.hours i{display:block;background:#22a6a6;border-radius:3px 3px 0 0;min-height:2px}</style></head><body><div class="wrap"><div class="row"><span id="hLogo" class="hlogo"></span><h1 class="sp"><span id="hName">Naše TV</span> · Programové studio</h1><label class="chk">Stanice <input id="station" value="Naše TV" style="width:120px;background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:5px 8px;font:inherit"></label> <button id="bTheme" class="sm">🌙 Tmavý</button> <label class="chk"><span data-i="language">Jazyk</span> <select id="lang"></select></label></div><div class="mut">RSS zprávy → třídění a hodnocení → automatický program relace → vysílání s avatarem. Ukázková verze; logika se později přenese do portálu na hostingu.</div><div class="userbar" id="userbar"><span class="mut">👤 Přihlášen:</span> <select id="curUser" data-ro-ok></select> <span id="curRoles"></span> <span class="sp"></span><span class="mut small" id="authNote">Ukázka: přepínání uživatelů nahrazuje přihlášení. V portálu: heslo + dvoufázové ověření.</span></div><div class="tabs grouped"><div class="tgroup"><span class="tgl">Start</span> <button data-t="tH" class="on">🏠 Přehled</button> <button data-t="t4" class="pultbtn">🎛 <span data-i="tab_air">Pult vysílání</span></button> <button data-t="tW">🗓 Rozvrh</button></div><div class="tgroup"><span class="tgl">Redakce</span> <button data-t="t1">1 · <span data-i="tab_sources">Zdroje</span> <span id="nItems"></span></button> <button data-t="t2">2 · <span data-i="tab_sort">Třídění</span> <span id="nStories"></span></button> <button data-t="t3">3 · <span data-i="tab_program">Program</span> <span id="nProg"></span></button> <button data-t="tK">Korespondenti</button></div><div class="tgroup"><span class="tgl">Pořady a výroba</span> <button data-t="tP">📺 Pořady</button> <button data-t="tV">🎬 Video zprávy</button> <button data-t="tM">🎙 Moderátoři</button></div><div class="tgroup"><span class="tgl">Finance a obchod</span> <button data-t="tB">💰 Rozpočet</button> <button data-t="tR">📢 Reklama</button> <button data-t="tI">🏪 Inzerenti</button></div><div class="tgroup"><span class="tgl">Správa</span> <button data-t="tS">📊 Statistika</button> <button data-t="tU">👥 Uživatelé a role</button> <button data-t="t0"><span data-i="tab_charter">Charta</span></button></div></div><div class="robar" id="robar">🔒 Tuto záložku máte jen pro čtení – změny může dělat jiná role.</div><div class="tab on" id="tH"><div class="card"><div class="row"><h2 class="sp" id="hHello">Přehled</h2><span id="hRoles"></span></div><p class="mut" id="hIntro"></p><div class="kpis" id="hKpis"></div></div><div class="flex2"><div class="card"><h2>Moje úkoly</h2><ul class="todo" id="hTodo"></ul></div><div class="card"><h2>Dnes ve vysílání</h2><ul class="plain" id="hToday"></ul><button class="sm" data-go="tW" data-ro-ok>Celý rozvrh →</button></div></div><div class="card"><h2>Rychlé odkazy</h2><div class="row" id="hLinks"></div></div></div><div class="tab" id="tW"><div class="card"><div class="row"><h2 class="sp">Týdenní rozvrh vysílání</h2><label class="chk">Nástěnka je vidět: <select id="wVis"></select></label> <label class="chk" title="Zprávy ve všední dny běží každý den ve stejné hodiny – úprava jednoho dne se propíše do Po–Pá"><input type="checkbox" id="wLock"> Pevné časy zpráv Po–Pá</label></div><p class="mut">Rozvrh určuje, kdy co běží, kdo moderuje a z jakých kategorií zdrojů se pořad skládá. Každý den má <b>profil</b> – přednastavené volby výběru zpráv (např. víkend: víc pozitivních zpráv a kultury, méně sporných témat). Z rozvrhu se generuje nástěnka pro diváky.</p><div class="row daytabs" id="wDays"></div></div><div class="card"><div class="row"><h2 class="sp" id="wDayTitle"></h2><label class="chk">Profil dne <select id="wProfile"></select></label> <button class="sm" id="wAdd">+ Přidat pořad</button> <button class="sm" id="wCopy">Kopírovat tento den do Po–Pá</button> <button class="sm" id="wReset">Obnovit výchozí rozvrh</button> <button class="sm" id="wExport" data-ro-ok>Kopírovat rozvrh (JSON)</button></div><div class="mut" id="wProfDesc" style="margin:4px 0 8px"></div><div class="tw"><table id="wTable"><thead><tr><th>Čas</th><th>Konec</th><th>Typ</th><th>Název</th><th>Moderuje</th><th>Min</th><th>Kategorie zdrojů</th><th></th></tr></thead><tbody></tbody></table></div><div class="note" id="wWarn" style="display:none"></div></div><div class="card"><div class="row"><h2 class="sp">Nástěnka – náhled</h2><span class="mut" id="wVisNote"></span></div><div class="board" id="wBoard"></div></div></div><div class="tab" id="tS"><div class="card"><div class="row"><h2 class="sp">Statistika diváků <span class="proto">UKÁZKOVÁ DATA</span></h2><label class="chk">Období <select id="sPer" data-ro-ok><option value="7">7 dní</option><option value="30" selected="selected">30 dní</option><option value="90">90 dní</option></select></label></div><p class="mut">Čísla jsou ukázková. V portálu je bude plnit vestavěný měřicí skript (bez cookies) a volitelně Matomo nebo Plausible. Údaje o věku a pohlaví se neodhadují – pocházejí jen z dobrovolného dotazníku v profilu diváka, a proto u nich uvádíme počet odpovědí.</p><div class="kpis" id="sKpis"></div></div><div class="sgrid"><div class="card"><h2>Země původu diváků</h2><div id="sCountry"></div><div class="mut small">Země podle IP adresy (GeoIP na serveru); IP adresa se hned zahodí.</div></div><div class="card"><h2>Jazyk poslechu</h2><div id="sLang"></div><div class="mut small">Jazyk, ve kterém divák portál poslouchá nebo čte (vlastní volba, jinak jazyk prohlížeče).</div></div><div class="card"><h2>Dárci a diváci zdarma</h2><div class="donut" id="sDonors"></div><div id="sDonTxt" class="mut small"></div></div><div class="card"><h2>Kraje ČR</h2><div id="sRegion"></div></div><div class="card"><h2>Věk <span class="mut" id="sAgeN"></span></h2><div id="sAge"></div><div class="mut small">Z dobrovolného dotazníku – nemusí odpovídat všem divákům.</div></div><div class="card"><h2>Zařízení a způsob sledování</h2><div id="sDev"></div></div><div class="card"><h2>Nejsledovanější pořady</h2><div id="sShows"></div></div><div class="card"><h2>Kdy se díváme</h2><div id="sHours" class="hours"></div><div class="mut small">Průměrný počet diváků podle hodiny – pomáhá ladit rozvrh.</div></div></div><div class="card"><h2>Zdroje analytiky</h2><div class="tw"><table id="sSrc"><thead><tr><th>Zdroj</th><th>Co poskytne</th><th>Soukromí</th><th>Stav</th></tr></thead><tbody></tbody></table></div><details style="margin-top:8px"><summary>Vestavěný měřicí skript pro portál (návrh)</summary><textarea readonly="readonly" id="sSnippet" data-ro-ok></textarea></details></div></div><div class="tab" id="tU"><div class="card"><div class="row"><h2 class="sp">Uživatelé administrace</h2></div><p class="mut">Každý uživatel může mít více rolí; jeho práva jsou součtem rolí (vždy platí vyšší oprávnění). Roli „Hlavní“ může přidělit jen jiný hlavní uživatel a vždy musí zůstat aspoň jeden aktivní.</p><div class="tw"><table id="uTable"><thead><tr><th>Jméno</th><th>E-mail</th><th>Role</th><th>Aktivní</th><th>2FA</th><th></th></tr></thead><tbody></tbody></table></div><div class="row adduser" style="margin-top:10px"><input id="uName" placeholder="Jméno a příjmení"><input id="uMail" placeholder="e-mail" type="email"><button class="pri" id="uAdd">+ Přidat uživatele</button><span id="uMsg" class="mut"></span></div></div><div class="card"><div class="row"><h2 class="sp">Role a oprávnění</h2><button class="sm" id="uMatReset">Výchozí oprávnění</button></div><p class="mut">✏ = úpravy, 👁 = jen čtení, – = záložka se nezobrazí. Matici může měnit jen role Hlavní.</p><div class="tw"><table id="uMatrix"></table></div></div><div class="card"><h2>Záznam změn</h2><ul class="plain small" id="uAudit"></ul></div></div><div class="tab" id="t0"><div class="card charter"><h2>Charta nezávislého vysílání a podpory demokracie</h2><div class="mut">Verze 0.1 – návrh k veřejné diskusi. Závazná pro redakci, přispěvatele i automatické nástroje portálu.</div><h3>Preambule</h3><p>Portál slouží veřejnosti. Je financován dobrovolnými příspěvky a nezávisí na žádné politické straně, státním orgánu ani jednotlivém dárci. Jeho posláním je pravdivě informovat, vzdělávat a posilovat demokratickou společnost, ve které si lidé mohou utvářet vlastní názor.</p><h3>Článek 1 – Pravdivost a ověřování</h3><p>Zveřejňujeme jen informace, které umíme doložit zdrojem. Každá zpráva uvádí, odkud pochází. Co nevíme jistě, výslovně označíme jako neověřené.</p><h3>Článek 2 – Oddělení zpráv, názorů a propagace</h3><p>Zpravodajství, komentář, propagační sdělení a reklama jsou vždy viditelně odlišeny. Každý příspěvek nese označení účelu a míry sporu (viz níže).</p><h3>Článek 3 – Nestrannost a pluralita</h3><p>Nepodporujeme žádnou stranu, hnutí ani kandidáta. U sporných témat dáváme prostor více stranám a jejich argumenty prezentujeme férově. Témata vybíráme podle důležitosti pro veřejnost, ne podle toho, komu prospějí.</p><h3>Článek 4 – Ochrana demokratických institucí</h3><p>Hájíme principy, na kterých stojí demokracie, bez ohledu na to, kdo je právě u moci: svobodné a férové volby, ústavu a právní stát, nezávislé soudy, svobodu projevu a médií, práva menšin a veřejnou kontrolu moci. Kritika konkrétních politiků a rozhodnutí je legitimní; útoky na samotné instituce a pravidla demokratické soutěže pojmenováváme.</p><h3>Článek 5 – Respekt a lidská důstojnost</h3><p>Nešíříme nenávist, nezesměšňujeme skupiny lidí a nezveřejňujeme soukromé údaje. U tragických událostí chráníme oběti a jejich blízké.</p><h3>Článek 6 – Mládež a senioři</h3><p>Pro mladé lidi připravujeme obsah, který rozvíjí kritické myšlení a mediální gramotnost. Pro starší lidi obsah srozumitelný, užitečný a potěšující, včetně ochrany před podvody a dezinformacemi.</p><h3>Článek 7 – Transparentnost umělé inteligence</h3><p>Avatar a hlas jsou syntetické a vždy tak označené. AI pomáhá třídit a připravovat texty, ale o zveřejnění rozhoduje člověk. Pravidla třídění jsou veřejná.</p><h3>Článek 8 – Nezávislé financování</h3><p>Žádný dárce nesmí financovat víc než stanovený podíl rozpočtu. Dárci nad určenou částku jsou zveřejněni. Dárci ani inzerenti nemají vliv na obsah.</p><h3>Článek 9 – Opravy a odpovědnost</h3><p>Chyby opravujeme rychle a viditelně, s uvedením, co bylo špatně. Každý může chybu nahlásit. Redakce zveřejňuje, kdo za obsah odpovídá.</p><h3>Článek 10 – Otevřenost</h3><p>Charta, pravidla třídění i hospodaření jsou veřejné. Změny charty se zveřejňují k připomínkám dopředu.</p><h3>Označení příspěvků</h3><p class="mut">Každá zpráva má <b>účel</b> a <b>míru sporu</b>. Automatika navrhne označení podle obsahu, redaktor ho potvrdí nebo změní. Diskutabilní a citlivé zprávy jdou do vysílání až po schválení.</p><div id="legend"></div></div></div><div class="tab" id="tB"><div class="card"><div class="row"><h2 class="sp">Veřejný rozpočet stanice – <span id="bMonth"></span> <span class="proto">PROTOTYP · UKÁZKOVÁ ČÍSLA</span></h2><button class="pri" id="bDonate">♥ Přispět</button></div><p class="mut">Stanice žije jen z dobrovolných příspěvků. Ukazujeme, kolik stojí měsíc provozu, kolik už se vybralo a co ještě chybí. Vybrané peníze pokrývají položky v pořadí podle priority (shora dolů). Pravidla podle charty, čl. 8: jeden dárce nejvýše <b>5 %</b> rozpočtu, dárci nad 10 000 Kč měsíčně jsou zveřejněni.</p><div class="kpis"><div class="kpi"><span class="mut">Potřebujeme / měsíc</span><span class="big" id="kNeed"></span></div><div class="kpi"><span class="mut">Vybráno</span><span class="big" id="kHave"></span></div><div class="kpi"><span class="mut">Ještě chybí</span><span class="big" id="kMiss"></span></div><div class="kpi"><span class="mut">Přispěvatelů</span><span class="big" id="kDon"></span><span class="mut" id="kAvg"></span></div></div><div class="pbar" style="height:18px"><i id="kBar"></i></div><div class="mut" id="kPct" style="margin-top:4px"></div></div><div class="card"><div class="row"><h2 class="sp">Položky rozpočtu</h2><label class="chk"><input type="checkbox" id="bEdit"> Upravit (redakce)</label></div><div class="tw"><table id="tBudget"><thead><tr><th>Položka</th><th>Kč / měsíc</th><th>Pokryto</th><th style="width:28%">Stav</th></tr></thead><tbody></tbody></table></div><div class="row" style="margin-top:8px;display:none" id="bEditRow"><span class="mut">Vybráno tento měsíc (Kč):</span><input type="number" id="bHave" style="width:130px"> <span class="mut">Přispěvatelů:</span><input type="number" id="bDonN" style="width:90px"> <span class="mut">Největší dárce (Kč):</span><input type="number" id="bTop" style="width:110px"></div><div id="bRule" class="note"></div></div><div class="card"><div class="row"><h2 class="sp">Poslední příspěvky (živě)</h2><label class="chk"><input type="checkbox" id="donSim" checked="checked"> Simulovat příchozí příspěvky (ukázka)</label></div><div id="donList" class="mut">Zatím žádné.</div></div></div><div class="modal" id="mDonate"><div class="box"><h2>Přispět na provoz <span class="proto">PROTOTYP</span></h2><p class="mut">Vyberte částku a frekvenci. Platební brána zatím není napojená – nic se neodešle ani nestrhne.</p><div class="amts" id="dAmts"><button>100 Kč</button><button class="on">200 Kč</button><button>500 Kč</button><button>1 000 Kč</button><input type="number" id="dOwn" placeholder="Jiná částka" style="width:120px;background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:6px 8px;font:inherit"></div><div class="row"><label class="chk"><input type="radio" name="dFreq" value="m" checked="checked"> Měsíčně</label><label class="chk"><input type="radio" name="dFreq" value="1"> Jednorázově</label></div><label class="chk" style="margin-top:8px"><input type="checkbox" id="dAnon"> Nechci být uveden(a) ve veřejném seznamu dárců</label><div id="dMsg" class="note" style="display:none"></div><div class="row" style="margin-top:12px"><button class="pri" id="dGo">Pokračovat k platbě</button><button id="dClose">Zavřít</button></div></div></div><div class="tab" id="tK"><div class="card"><div class="row"><h2 class="sp">Staň se naším korespondentem <span class="proto">PROTOTYP</span></h2><label class="chk">Pohled: <select id="kView"><option value="k">Korespondent</option><option value="m">Moderátor redakce</option></select></label></div><p class="mut">Dobrovolní korespondenti posílají zprávy, fotky a videa ze svého okolí. Každý příspěvek projde moderací a ověřením podle charty, než se dostane do vysílání. Prototyp: data zůstávají jen v tomto prohlížeči, nic se neodesílá.</p></div><div id="kReg" class="card form"><h2>1 · Registrace</h2><div class="grid2"><div><label>Jméno a příjmení *</label><input id="rName"></div><div><label>E-mail *</label><input id="rMail" type="email"></div><div><label>Telefon</label><input id="rTel"></div><div><label>Region / obec *</label><input id="rReg" placeholder="např. Liberec"></div><div><label>Oblast zájmu</label><select id="rTopic"><option>Region a obec</option><option>Zdraví</option><option>Školství</option><option>Kultura</option><option>Sport</option><option>Doprava</option><option>Životní prostředí</option></select></div><div><label>Profese (nepovinné)</label><input id="rJob"></div></div><label class="chk"><input type="checkbox" id="rCh"> Přečetl(a) jsem chartu a budu ji dodržovat *</label> <label class="chk"><input type="checkbox" id="rGdpr"> Souhlasím se zpracováním osobních údajů pro účely spolupráce *</label><p class="mut">Po registraci následuje ověření totožnosti (v ostré verzi např. bankovní identitou). Do té doby nesou příspěvky označení „neověřený přispěvatel“.</p><button class="pri" id="rGo">Zaregistrovat</button> <span id="rMsg" class="mut"></span></div><div id="kAcc" class="card form" style="display:none"><div class="row"><h2 class="sp">2 · Můj účet</h2><button class="sm" id="rOut">Smazat účet</button></div><div id="accInfo" class="mut"></div><h2 style="margin-top:14px">3 · Odeslat příspěvek k moderaci</h2><div class="grid2"><div><label>Titulek *</label><input id="pTitle"></div><div><label>Místo a čas události *</label><input id="pWhere" placeholder="Liberec, 19. 11. 2026 10:30"></div><div><label>Typ</label><select id="pType"><option>Zpráva</option><option>Fotoreportáž</option><option>Video</option><option>Pozvánka na akci</option><option>Názor / komentář</option></select></div><div><label>Zdroj informace</label><select id="pSrc"><option>Byl(a) jsem očitým svědkem</option><option>Oficiální zdroj (úřad, policie…)</option><option>Zprostředkovaně (od jiné osoby)</option></select></div></div><label>Text *</label><textarea id="pText" placeholder="Co, kdo, kde, kdy, proč. Jen ověřená fakta, bez osobních údajů třetích osob."></textarea> <label>Příloha (foto / video)</label><input type="file" id="pFile" accept="image/*,video/*"> <label class="chk"><input type="checkbox" id="pRights"> Přílohu jsem pořídil(a) sám/sama nebo mám souhlas autora a zobrazených osob</label> <button class="pri" id="pGo">Odeslat k moderaci</button> <span id="pMsg" class="mut"></span><h2 style="margin-top:14px">Moje příspěvky</h2><div id="myPosts" class="mut">Zatím žádné.</div></div><div id="kMod" class="card" style="display:none"><h2>Fronta moderace</h2><p class="mut">Moderátor zkontroluje fakta, zdroj a práva k přílohám. Schválený příspěvek se přidá jako zdroj „Dobrovolní korespondenti“ do třídění a programu.</p><div id="modList" class="mut">Fronta je prázdná.</div></div></div><div class="tab" id="t1"><div class="card"><h2>Načtení RSS</h2><div class="note">Tato ukázková stránka nesmí sama stahovat z jiných webů (bezpečnostní omezení). Proto: <b>ukázková data</b> (smyšlené zprávy pro test), nebo <b>nahrajte RSS soubor</b> (otevřete adresu RSS v prohlížeči, uložte jako .xml), nebo <b>vložte text RSS</b>. V portálu na hostingu bude RSS stahovat server sám, automaticky každých pár minut.</div><div class="row"><button class="pri" id="bSample">Načíst ukázková data</button> <label class="file">Nahrát RSS (.xml, i více)<input type="file" id="fRss" accept=".xml,.rss,.atom,application/rss+xml,application/xml,text/xml" multiple="multiple"></label> <button id="bClear">Vymazat vše</button></div><p class="mut" style="margin:10px 0 4px">Nebo vložte obsah RSS/Atom (XML):</p><textarea id="taRss" placeholder="&lt;rss&gt;…&lt;/rss&gt;"></textarea><div class="row" style="margin-top:6px"><input id="srcName" placeholder="Název zdroje" style="background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:7px 10px;font:inherit"><button id="bPaste">Přidat vložený zdroj</button></div></div><div class="card"><h2>Načtené zdroje</h2><div id="srcList" class="mut">Zatím nic.</div></div><div class="card"><div class="row"><h2 class="sp">Registr zdrojů Naše TV</h2><button class="sm" id="rgRec">Doporučený výběr (ověřené, důvěra ★★+)</button><button class="sm" id="rgNone">Zrušit výběr</button></div><p class="mut" style="margin:4px 0 8px">Zaškrtnuté zdroje stanice odebírá: načítač níže je stahuje sám podle intervalu každého zdroje a donačítá jen zprávy novější než poslední načtení. Kde serverový načítač není (tato ukázka), lze zdroj otevřít, uložit jako .xml a nahrát tlačítkem <b>Nahrát .xml</b>. Média zakázaná v EU vybrat nelze.</p><div class="row"><input id="rgQ" placeholder="Hledat" style="flex:1;min-width:140px;background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:6px 9px;font:inherit"> <select id="rgCat"></select><select id="rgReg"></select><select id="rgLang"></select><label class="chk"><input type="checkbox" id="rgOnly"> jen vybrané</label></div><div id="rgCnt" class="mut" style="margin:6px 0"></div><div id="rgList" style="max-height:420px;overflow:auto;border:1px solid var(--line);border-radius:10px;padding:4px 8px"></div><input type="file" id="rgFile" accept=".xml,.rss,.atom,application/rss+xml,application/xml,text/xml" style="display:none"></div><div class="card" id="autoCard"><div class="row"><h2 class="sp">Automatické načítání vybraných zdrojů</h2><label class="chk"><input type="checkbox" id="alOn"> obnovovat automaticky</label> <button class="pri" id="alNow">⟳ Načíst vybrané teď</button><button class="sm" id="alForce" title="Stáhnout znovu i zdroje, kterým ještě neuplynul interval">Vynutit vše</button></div><div class="row" style="margin:2px 0 6px"><span class="mut">Načítat:</span> <label class="chk"><input type="radio" name="alMode" value="ch"> kanály Naší TV (agregátor) – doporučeno</label> <label class="chk"><input type="radio" name="alMode" value="src"> jednotlivé zdroje z registru</label></div><div class="row" id="alChs" style="margin-bottom:6px"></div><p class="mut" style="margin:4px 0 8px" id="alMode">Zjišťuji, jestli je dostupný serverový načítač…</p><div class="tw"><table id="alTable"><thead><tr><th>Zdroj</th><th>Interval</th><th>Načteno</th><th>Zdroj aktualizován</th><th>Nejnovější zpráva</th><th>Nové</th><th>Další</th><th>Stav</th></tr></thead><tbody></tbody></table></div></div></div><div class="tab" id="t2"><div class="card"><h2>Pravidla hodnocení</h2><div class="grid2"><label class="w">Čerstvost – poločas (hodiny): <b id="vHalf"></b><input type="range" id="wHalf" min="1" max="24" value="6"></label> <label class="w">Váha čerstvosti: <b id="vFresh"></b><input type="range" id="wFresh" min="0" max="50" value="35"></label> <label class="w">Váha potvrzení více zdroji: <b id="vCorr"></b><input type="range" id="wCorr" min="0" max="50" value="25"></label> <label class="w">Váha důležitosti tématu: <b id="vImp"></b><input type="range" id="wImp" min="0" max="50" value="20"></label> <label class="w">Váha regionu (Liberecký kraj): <b id="vReg"></b><input type="range" id="wReg" min="0" max="50" value="15"></label> <label class="w">Starší než (h) vyřadit: <b id="vMax"></b><input type="range" id="wMax" min="6" max="96" value="48"></label></div><div class="row" style="margin-top:8px"><span class="mut">Kategorie ve vysílání:</span><span id="catChk" class="row"></span></div></div><div class="card"><div class="row"><h2 class="sp">Příběhy seřazené podle skóre</h2><span class="mut">Stejná zpráva z více zdrojů = jeden příběh.</span></div><div class="tw"><table id="tStories"><thead><tr><th>Skóre</th><th>Zpráva</th><th>Označení</th><th>Kategorie</th><th>Zdroje</th><th>Stáří</th></tr></thead><tbody></tbody></table></div></div></div><div class="tab" id="t3"><div class="card"><h2>Sestavení relace</h2><div class="row"><label class="chk">Začátek <input type="time" id="pStart"></label> <label class="chk">Délka (min) <input type="number" id="pLen" min="2" max="60" value="8" style="width:70px"></label> <label class="chk">Max. zpráv z 1 zdroje <input type="number" id="pPerSrc" min="1" max="20" value="4" style="width:60px"></label> <select id="pAud"><option value="">Relace: pro všechny</option><option value="mladez">Relace: pro mládež</option><option value="senior">Relace: pro seniory</option></select> <select id="pStyle"></select> <select id="pProfile"></select><input id="pCats" placeholder="kategorie: všechny" title="Omezit relaci na kategorie (oddělte čárkou)" style="width:150px"><select id="pSlot"></select> <button class="pri" id="bBuild">Sestavit program</button> <button id="bExport">Kopírovat program (JSON)</button></div><div style="margin:8px 0"><b>Zdroje v této relaci:</b> <span id="progSrc"></span></div><div class="mut" id="pProfNote"></div><div class="note">Šablona relace: úvod s titulky → hlavní zprávy (3 nejvýše hodnocené) → bloky podle kategorií s limity → závěr. Citlivé a diskutabilní zprávy se nevysílají, dokud je redaktor nezaškrtne ✔. Každá položka nese označení podle charty. Relace pro mládež / seniory zvýhodní zprávy s odpovídajícím účelem. Pořadí lze upravit šipkami.</div></div><div class="card"><div class="row"><h2 class="sp">Program</h2><span id="progSum" class="mut"></span></div><div class="tw"><table id="tProg"><thead><tr><th>Čas</th><th>✔</th><th>Položka</th><th>Zdroj</th><th>Délka</th><th></th></tr></thead><tbody></tbody></table></div></div></div><div class="tab" id="t4"><div class="pult"><div class="pcell now"><div class="plab">TEĎ V ROZVRHU</div><div id="pNow" class="pval">–</div><div id="pNowBar" class="pbar"><i></i></div></div><div class="pcell"><div class="plab">DALŠÍ</div><div id="pNext" class="pval">–</div><div id="pNextIn" class="mut small"></div></div><div class="pcell"><div class="plab">RELACE</div><div id="pRel" class="pval">–</div><div id="pRelSub" class="mut small"></div></div><div class="pcell click" data-go="t3"><div class="plab">ČEKÁ NA SCHVÁLENÍ</div><div id="pPend" class="pval">0</div><div class="mut small">sporné / citlivé zprávy</div></div><div class="pcell click" data-go="t1"><div class="plab">ZDROJE</div><div id="pSrc" class="pval">–</div><div id="pSrcSub" class="mut small"></div></div><div class="pcell"><div class="plab">DIVÁCI</div><div id="pView" class="pval">–</div><div class="mut small">ukázková simulace</div></div></div><div class="row pquick"><button class="pri" id="qNext">⚡ Sestavit relaci pro další pořad</button> <button id="qFetch">⟳ Načíst zdroje</button> <button id="qBrk">🔴 Mimořádná zpráva…</button> <span class="sp"></span><span class="mut small" title="Klávesové zkratky platí, když nepíšete do pole">⌨ mezerník = spustit/zastavit · N = další · M = zvuk · B = mimořádná zpráva</span></div><div class="flex2"><div><div id="stage"></div><div class="row" style="margin-top:8px"><button class="pri" id="bOnAir">▶ <span data-i="start">Spustit vysílání</span></button> <button id="bStop">■ <span data-i="stop">Zastavit</span></button> <button id="bSkip">⏭ <span data-i="next">Další</span></button> <button id="bVoice">🔇 <span data-i="voice_off">Hlas: vypnutý</span></button> <label class="chk"><input type="checkbox" id="showLbl" checked="checked"> <span data-i="show_labels">Zobrazovat označení</span></label> <label class="chk"><input type="checkbox" id="lvTk" checked="checked"> Žlutá lišta</label><label class="chk"><input type="checkbox" id="lvBrk" checked="checked"> Červená lišta</label><label class="chk"><input type="checkbox" id="lvLive" checked="checked"> Diváci a rozpočet</label> <span class="sp"></span><span id="onAir" class="mut"></span></div><div class="row" style="margin-top:6px"><input id="brkTxt" placeholder="Mimořádná zpráva do červené lišty (jinak automaticky u čerstvé výstrahy)" style="flex:1;min-width:200px;background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:7px 10px;font:inherit"><button id="brkOn" class="sm">Zobrazit</button><button id="brkOff" class="sm">Skrýt</button></div><p class="mut" style="margin:4px 0 0">Počet diváků je v ukázce simulovaný (večerní špička); v portálu ho počítá server z aktivních přehrávačů. Příspěvky ve vysílání a v Rozpočtu přibývají simulovaně – v portálu z platební brány.</p><div class="note" id="vNote">Hlas: v portálu na hostingu namluví každou zprávu server (Piper / espeak-ng) s přesnými časy slov. Tato stránka může použít jen hlas prohlížeče, pokud ho zařízení má; časování je odhad. Bez hlasu běží titulky a avatar podle hodin.<br><b>Označení:</b> když je vypnete, v obraze zůstane jen „Propagační sdělení“ a „Názor / komentář“ – charta (čl. 2) vyžaduje, aby propagace a názor byly vždy odlišené od zpráv.<br><b>Jazyk:</b> rozhraní vysílání je přeložené do 24 jazyků EU a ukrajinštiny. Obsah zpráv přeloží vestavěný překladač prohlížeče, pokud ho prohlížeč má (např. nový Chrome na počítači). Jinak zůstanou v původním znění s označením. V portálu na hostingu bude překládat server.</div></div><div><div class="card"><div class="row"><h2 class="sp" data-i="rundown">Na programu</h2><span class="mut small">▶ přehrát odsud · ✓ schválit · ✕ vyřadit · ↑↓ pořadí</span></div><div id="trNote" class="mut"></div><div id="rundown" class="mut">Nejdřív sestavte program (krok 3).</div></div><details class="card"><summary><b>Znělky a odpočty</b> <span class="mut small">– pustit ručně</span></summary><p class="mut" style="margin:0 0 6px">Pustí se hned, potom vysílání pokračuje.</p><div class="bmpgrid" id="bmpBtns"></div><label class="chk" style="margin-top:8px"><input type="checkbox" id="autoBmp" checked="checked"> Automaticky vkládat znělky do programu</label><div class="row" style="margin-top:6px"><label class="chk"><input type="checkbox" id="bmpMusic" checked="checked"> 🎵 Hudba ve znělkách</label> <label class="chk">Hlasitost <input type="range" id="bmpVol" min="0" max="100" value="70" style="width:110px"></label></div><p class="mut" style="margin:4px 0 0">Krátké původní motivy, syntetizované přímo v prohlížeči – žádné cizí nahrávky. Na iPhonu hraje hudba i v tichém režimu, zkontrolujte ale hlasitost médií.</p></details></div></div></div><div class="tab" id="tR"><div class="card"><div class="row"><h2 class="sp">Kontextová reklama ve vysílání <span class="proto">PROTOTYP · FIKTIVNÍ ZADAVATELÉ</span></h2><button id="adExport" class="sm">Export nastavení (JSON)</button><button id="adImportBtn" class="sm">Import</button><button id="adReset" class="sm">Výchozí nastavení</button></div><p class="mut">Reklama se vkládá podle pravidel, ne pomocí AI: každé pravidlo říká, <b>v jakém kontextu</b> (blok, pozadí, kategorie, účel, klíčová slova), <b>kam</b> (před zprávu, za ni, za konec bloku, před závěr) a <b>které spoty</b> se střídají. Spot je vždy označen „REKLAMA“ a zadavatelem.</p><textarea id="adImport" style="display:none;min-height:120px" placeholder="Vložte JSON s nastavením a klikněte znovu na Import"></textarea></div><div class="card form"><h2>Obecná pravidla</h2><div class="row" style="gap:14px"><label class="chk"><input type="checkbox" id="asOn"> Reklama ve vysílání zapnutá</label> <label class="chk">Max. spotů za relaci <input type="number" id="asMax" min="0" max="20" style="width:60px"></label> <label class="chk">Max. podíl času (%) <input type="number" id="asShare" min="0" max="50" style="width:60px"></label> <label class="chk">Min. zpráv mezi spoty <input type="number" id="asGap" min="0" max="10" style="width:60px"></label></div><div class="row" style="gap:14px;margin-top:6px"><label class="chk"><input type="checkbox" id="asShift"> Nikdy hned po citlivé zprávě (posunout dál)</label> <label class="chk"><input type="checkbox" id="asCtrv"> Nikdy hned po sporné zprávě</label> <label class="chk"><input type="checkbox" id="asUntr"> Nikdy u nepřeložené zprávy</label></div><div class="row" style="margin-top:6px"><span class="mut">Bloky bez reklamy:</span><span id="asBan" class="row"></span></div><div class="row" style="margin-top:10px;gap:10px"><span class="mut">Neprodané místo (pravidlo bez aktivního spotu):</span> <select id="asFill" style="background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:6px;padding:4px;font:inherit"><option value="none">nechat prázdné (relace se zkrátí)</option><option value="promo">upoutávka stanice (výzva k příspěvku)</option><option value="vast">externí síť – VAST (jen web/online, simulace)</option></select></div><div id="asVastBox" style="margin-top:6px"><label>Adresa VAST dotazu (Google Ad Manager nebo jiná síť) – kontext se přidá jako <code>cust_params</code></label><input id="asVast"><div class="row" style="margin-top:4px"><span class="mut">Blokované kategorie v síti:</span><span id="asVBlock" class="row"></span></div><p class="mut" style="margin:4px 0 0">Externí síť jen jako doplněk: kontext posíláme bez osobních údajů (bez cookies), personalizovaná reklama by vyžadovala souhlas (CMP). Do lineárního TV/rádiového vysílání se externí spoty nevkládají.</p></div></div><div class="card"><div class="row"><h2 class="sp">Reklamní spoty</h2><button class="sm" id="adAdd">+ Přidat spot</button></div><div class="tw"><table id="tAds"><thead><tr><th>Aktivní</th><th>Spot / zadavatel</th><th>Titulek a text</th><th>Vzhled</th><th>Délka</th><th></th></tr></thead><tbody></tbody></table></div></div><div class="card"><div class="row"><h2 class="sp">Pravidla vkládání</h2><button class="sm" id="ruAdd">+ Přidat pravidlo</button></div><div class="tw"><table id="tRules"><thead><tr><th>Aktivní</th><th>Název</th><th>Kontext</th><th>Hodnota</th><th>Umístění</th><th>Spoty (střídají se)</th><th>Priorita</th><th>Max/relace</th><th></th></tr></thead><tbody></tbody></table></div></div><div class="flex2"><div class="card"><h2>Náhled spotu</h2><div id="adStage" style="width:100%;aspect-ratio:16/9;border-radius:10px;overflow:hidden;background:#000;color:#aaa;display:flex;align-items:center;justify-content:center">Klikněte na ▶ u spotu</div></div><div class="card"><div class="row"><h2 class="sp">Výsledek pro aktuální program</h2><button class="pri sm" id="adRebuild">Přestavět program</button></div><div id="adLog" class="mut">Sestavte program (krok 3).</div></div></div></div><div class="tab" id="tI"><div class="card"><h2>Inzertní portál <span class="proto">PROTOTYP · BEZ PLATEB · DATA JEN V TOMTO PROHLÍŽEČI</span></h2><p class="mut">Místní firma si sama objedná kontextový spot (např. „před předpovědí počasí“), redakce ho zkontroluje podle charty a po schválení se automaticky zařadí do pravidel vysílání. Ceny jsou ukázkové. V portálu na hostingu přibude ověření firmy, smlouva, platba (GoPay/Comgate) a faktura.</p></div><div class="flex2"><div><div class="card form" id="inzAccBox"></div><div class="card form" id="inzOrderBox"></div><div class="card"><h2>Moje objednávky a odvysílání</h2><div class="tw"><table id="tOrders"><thead><tr><th>Objednávka</th><th>Kontext</th><th>Období</th><th>Stav</th><th>Odvysíláno</th><th>Čerpáno</th></tr></thead><tbody></tbody></table></div></div></div><div><div class="card"><h2>Redakční schválení</h2><div id="inzQueue" class="mut"></div></div><div class="card"><h2>Náhled objednávky</h2><div id="inzStage" style="width:100%;aspect-ratio:16/9;border-radius:10px;overflow:hidden;background:#000;color:#aaa;display:flex;align-items:center;justify-content:center">Klikněte na ▶ Náhled</div></div><div class="card"><h2>Zakázané kategorie (charta)</h2><div class="mut" id="inzBan"></div></div></div></div></div><div class="tab" id="tM"><div class="card"><div class="row"><h2 class="sp">Virtuální moderátoři</h2><label class="chk">Relaci moderuje: <select id="persMode" style="background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:5px;font:inherit"></select></label></div><p class="mut">Všechny postavy jsou vymyšlené a kreslené počítačem – nejsou podobou žádné skutečné osoby. Ve vysílání mají vždy jmenovku s označením „virtuální moderátor/ka · AI“ (charta, čl. 3). Každá postava má svou specializaci, styl řeči (tempo a výšku hlasu) a profil. Šaty a saka se střídají podle dne a pořadí vstupu.</p></div><div class="flex2"><div id="persGrid" class="persgrid"></div><div><div class="card" style="position:sticky;top:8px"><h2>Ukázka moderátora</h2><div id="persStage" style="width:100%;aspect-ratio:16/9;background:#000;border-radius:10px;overflow:hidden"></div><p class="mut" style="margin:6px 0 0">Hlas zní, jen pokud je zapnutý „Hlas“ ve Vysílání a zařízení má hlas prohlížeče.</p></div></div></div></div><div class="tab" id="tP"><div class="card"><h2>Strukturované pořady <span class="proto">PROTOTYP</span></h2><p class="mut">Pořad je <b>předpřipravený scénář</b>: vygeneruje se z dat nebo zdrojů, redakce ho upraví a schválí, a teprve pak jde do vysílání – nic se negeneruje naživo. Každý pořad má svého virtuálního moderátora, vlastní znělku a uvedený zdroj dat.</p><div id="showCat" class="showcat"></div></div><div class="flex2"><div><div class="card form" id="showForm"><h2>Vyberte pořad nahoře</h2></div><div class="card" id="scriptBox" style="display:none"></div></div><div><div class="card" style="position:sticky;top:8px"><h2>Náhled pořadu</h2><div id="showStage" style="width:100%;aspect-ratio:16/9;background:#000;border-radius:10px;overflow:hidden"></div><div id="showNow" class="mut" style="margin-top:6px"></div><div class="row" style="margin-top:6px"><button class="sm" id="shStop">■ Zastavit náhled</button></div></div><div class="card"><h2>Knihovna scénářů</h2><div id="scriptLib" class="mut">Zatím nic.</div></div></div></div></div><div class="tab" id="tV"><div class="flex2"><div><div id="vStage" class="vstage"><video id="vVid" playsinline preload="auto"></video><svg id="vSvg" viewBox="0 0 1600 900" preserveAspectRatio="none"></svg><div id="vHtml"></div><div id="vHint" class="vhint"></div></div><div class="row" style="margin-top:8px"><button class="pri" id="vPlay">▶</button> <span id="vTime" class="mut" style="font-variant-numeric:tabular-nums">0:00 / 0:00</span> <input type="range" id="vSeek" min="0" max="1000" value="0" class="sp"> <button id="vMute">🔇</button><button id="vFs">⛶</button></div><div class="row" style="margin-top:6px"><button id="vSample">Ukázkové video</button> <label class="file">Nahrát vlastní video<input type="file" id="vFile" accept="video/*"></label> <label class="chk"><input type="checkbox" id="vShow" checked="checked"> Zobrazovat poznámky</label></div><p class="mut">Ukázkové video je kreslené (nemám tu přístup ke skutečným záběrům). Nahrajte vlastní záznam z telefonu – poznámky fungují nad jakýmkoli videem. Video zůstává jen v tomto prohlížeči.</p></div><div><div class="card"><h2>Poznámky podle kontextu zprávy</h2><div class="row"><select id="vStory" class="sp"></select><button class="pri" id="vAuto">Vygenerovat</button></div><p class="mut" style="margin:6px 0 0">Z textu zprávy vznikne: popisek (titulek, místo, datum), mapka s místem, fakta, označení podle charty, upozornění u sporných a citlivých témat a uvedení zdroje videa.</p></div><div class="card"><h2>Ruční poznámka</h2><div class="row"><select id="vType"><option value="callout">Popisek s ukazatelem</option><option value="arrow">Šipka (2 kliky)</option><option value="ring">Zvýraznění kruhem</option><option value="blur">Rozmazání – anonymizace (2 kliky)</option><option value="comment">Komentář redakce</option></select> <label class="chk">na <input type="number" id="vDur" value="4" min="1" max="60" style="width:56px"> s</label></div><input id="vText" placeholder="Text poznámky (např. Zde se tvoří kolona)" style="width:100%;margin-top:6px;background:var(--inp);color:var(--ink);border:1px solid var(--bd);border-radius:8px;padding:7px 9px;font:inherit"><div class="row" style="margin-top:6px"><button id="vPlace">➕ Umístit do videa</button><span class="mut" id="vPlaceMsg"></span></div></div><div class="card"><div class="row"><h2 class="sp">Poznámky na časové ose</h2><button class="sm" id="vClear">Smazat vše</button><button class="sm" id="vExport">JSON</button></div><div id="vList" class="mut">Zatím žádné.</div></div></div></div></div><p class="mut">Ukázková data jsou smyšlená a slouží jen k vyzkoušení třídění. U skutečných RSS se používá jen titulek a krátký úryvek, vždy se zdrojem.</p></div><script src="../assets/svgplayer.js"></script><script>!function(){"use strict";var e={zpravy:{name:"zpravy",bg1:"rgb(11,22,48)",bg2:"rgb(20,38,77)",accent:"rgb(242,184,75)",alert:"rgb(229,56,59)",skin:"rgb(233,199,168)",hair:"rgb(58,42,34)",outfit:"rgb(42,63,120)",outline:null,eye:"normal",avatar:!0,ink:null,panel:null,head:3.12,body:2.66,label:"Zpravodajské studio",rate:1},svetly:{name:"svetly",bg1:"rgb(246,248,252)",bg2:"rgb(222,230,242)",accent:"rgb(0,102,204)",alert:"rgb(206,38,54)",skin:"rgb(236,200,172)",hair:"rgb(70,50,40)",outfit:"rgb(0,70,140)",out