unction(){document.body.classList.toggle("dark");try{localStorage.setItem("studioTheme",document.body.classList.contains("dark")?"dark":"light")}catch(e){}Rn()},Rn(),k(),t("bSample").onclick=function(){n=n.filter(function(e){return"Dobrovolní korespondenti"===e.name}),[["Ukázkový zdroj A – zpravodajství",[[.5,"Kraj vyhlásil výstrahu před silným větrem na horách","Meteorologové varují před nárazy větru až sto kilometrů za hodinu v Jizerských horách a Krkonoších. Výstraha platí do zítřejšího rána. Hasiči doporučují nevycházet do lesů."],[1.2,"Vláda schválila nová pravidla pro elektronické recepty","Změna má zjednodušit předepisování opakovaných léků chronickým pacientům. Lékař bude moci vystavit recept až na rok. Pravidla začnou platit od ledna."],[2,"Ceny potravin v říjnu mírně klesly","Podle statistiků zlevnilo hlavně ovoce a zelenina. Meziroční inflace zpomalila. Ekonomové čekají další pokles na začátku příštího roku."],[3.5,"Na Ještědu začala příprava sjezdovek","Provozovatel areálu zahájil technické zasněžování. Pokud vydrží mrazy, sezona by mohla začít o víkendu. Cena permanentky zůstává stejná jako loni."],[5,"Evropská unie jedná o společném nákupu energie","Ministři členských států se sešli v Bruselu. Cílem je snížit ceny plynu před zimou. Dohoda zatím nepadla, jednání bude pokračovat příští týden."],[9,"Liberecký hokejový tým vyhrál na ledě soupeře","Domácí zvítězili po prodloužení. Rozhodující gól padl ve třetí minutě prodloužení. Tým se posunul na čtvrté místo tabulky."],[2.2,"Ústavní soud projedná stížnost na volební zákon","Soud posoudí, zda pravidla pro přepočet hlasů odpovídají ústavě. Rozhodnutí se čeká na jaře. Navrhovatelé tvrdí, že zákon znevýhodňuje menší strany, ministerstvo s tím nesouhlasí."],[6,"Obce v kraji kritizují plánovanou reformu financování","Starostové tvrdí, že reforma sníží příjmy malých obcí. Ministerstvo financí odpovídá, že celkové příjmy obcí porostou. Debata bude pokračovat ve Sněmovně."],[1.5,"Předpověď počasí: o víkendu přijde první sníh i na silnice","Meteorologové čekají sněžení od 600 metrů, v noci mrazy až minus osm stupňů. Na silnicích se může tvořit náledí. Řidiči by měli mít zimní výbavu."],[20,"Muzeum otevřelo výstavu o historii sklářství","Výstava představuje přes tři sta exponátů z regionálních skláren. Potrvá do konce března. Vstup pro seniory je zvýhodněný."]]],["Ukázkový zdroj B – region",[[.8,"Výstraha před větrem: na horách hrozí polámané stromy","Silný vítr se čeká v Jizerských horách a Krkonoších. Platí výstraha meteorologů. Lidé by se měli vyhnout lesům a zajistit volné předměty."],[1.5,"E-recepty pro chroniky půjdou vystavit až na rok","Vláda schválila úpravu elektronických receptů. Opakované recepty ušetří pacientům cesty k lékaři. Novinka platí od ledna."],[2.5,"Na silnici u Turnova se srazila tři auta","Při nehodě se zranili dva lidé, záchranáři je převezli do nemocnice. Silnice byla na dvě hodiny uzavřená. Policie příčinu vyšetřuje."],[4,"Ministerstvo zdravotnictví připomíná očkování proti chřipce","Očkování je hrazené seniorům nad 65 let a chronicky nemocným. Nejvhodnější doba je do konce prosince. Objednat se lze u praktického lékaře."],[7,"Summit ve Varšavě řešil bezpečnost ve střední Evropě","Představitelé sousedních států se shodli na užší spolupráci. Konkrétní kroky představí na jaře. Česko zastupoval ministr zahraničí."],[3,"Gymnázium v Jablonci spouští kurz mediální gramotnosti","Studenti se naučí rozpoznat dezinformace a ověřovat zdroje na sociálních sítích. Kurz povedou novináři a učitelé. Zapojit se mohou i další školy v kraji."],[30,"Festival dokumentárních filmů hlásí rekordní návštěvu","Letošní ročník navštívilo přes čtyřicet tisíc diváků. Vítězný snímek se zabýval proměnami venkova. Příští ročník bude opět na podzim."]]],["Ukázkový zdroj C – zdraví",[[1,"Praktičtí lékaři začínají s očkováním proti chřipce","Očkování proti chřipce hradí pojišťovny seniorům nad 65 let a chronicky nemocným. Lékaři doporučují nečekat. Ochrana nastupuje asi za dva týdny."],[3,"Nemocnice v Liberci rozšiřuje urgentní příjem","Nová část urgentu má zkrátit čekání pacientů. Stavba potrvá do léta. Provoz nemocnice zůstává bez omezení."],[2,"Městská knihovna zve seniory na kurz chytrých telefonů","Kurz je zdarma a začíná příští týden. Senioři se naučí videohovory a jak poznat podvodné zprávy. Přihlásit se lze na pobočkách."],[6,"Lékaři varují před smogem, citliví lidé mají omezit pobyt venku","Rozptylové podmínky jsou kvůli inverzi špatné. Astmatici a senioři by měli omezit pohyb venku. Situace by se měla zlepšit s příchodem větru."]]],["Sample source D – Europe (EN)",[[1.4,"EU ministers agree on joint gas purchases before winter","Energy ministers meeting in Brussels agreed to coordinate gas purchases. The plan aims to lower prices for households. Details will be published next week."],[4,"Alpine resorts open early after heavy snowfall","Several ski areas in Austria and Italy opened their slopes ahead of schedule. Operators expect a strong season. Avalanche risk remains moderate."]]],["Beispielquelle E – Sachsen (DE)",[[2.4,"Sachsen: Winterreifenpflicht bei Glätte – Polizei kontrolliert verstärkt","Nach dem ersten Schnee kontrolliert die Polizei in Sachsen verstärkt die Bereifung. Wer bei Glätte mit Sommerreifen fährt, riskiert ein Bußgeld. Die Polizei rät, die Reifen jetzt zu wechseln."]]]].reduce(function(e,t){return e.then(function(){return U(V((e=t[0],n=t[1],a=Date.now(),'<rss version="2.0"><channel><title>'+e+"</title>"+n.map(function(e){return"<item><title>"+E(e[1])+"</title><link>https://example.org/"+encodeURIComponent(e[1].slice(0,20))+"</link><description>"+E(e[2])+"</description><pubDate>"+new Date(a-36e5*e[0]).toUTCString()+"</pubDate></item>"}).join("")+"</channel></rss>")));var e,n,a})},Promise.resolve())},Z(),G(),X(),vt(),Mt();var _n=["Pondělí","Úterý","Středa","Čtvrtek","Pátek","Sobota","Neděle"],Dn=["Po","Út","St","Čt","Pá","So","Ne"],Vn={vsedni:{n:"Všední den",d:"Standardní zpravodajství, pevné časy zpráv, důraz na infor